//
// designlang Figma plugin — imports a `*-figma-variables.json` payload
// (produced by `designlang <url>`) into Figma: variables (with aliases, scopes and
// code syntax), text styles, effect styles and, optionally, a Button component.
//
// Accepted payload shapes (unknown keys are ignored):
//   v2 / formatter output (src/formatters/figma.js):
//     { version: 2, collections: [{ name, modes: ["light", "dark"], variables: [{ name, type, values: { light, dark } }] }],
//       textStyles: [...], effectStyles: [...], components: [...] }
//   v1 per-mode:
//     { collections: [{ name, modes: [{ name, variables: [{ name, type, value }] }] }] }

// Imports a designlang Figma payload (v1 or v2) into the open Figma file.
//
// This function must stay self-contained: no imports, no references to module
// scope. It is serialized with `.toString()` into figma-plugin/code.js (see
// scripts/build-figma-plugin.mjs) and into the `figma_plan` MCP script, and
// both run it against a live `figma` global.
//
// Re-runs are idempotent: collections, variables, text styles and effect
// styles are upserted by name.
async function importDesignSystem(figma, payload, opts) {
  opts = opts || {};
  const raw = payload && Array.isArray(payload.collections) ? payload.collections : [];
  if (raw.length === 0) throw new Error("No `collections` array found in payload.");

  const result = { collections: 0, variables: 0, textStyles: 0, effectStyles: 0, components: 0, fontFallbacks: [] };

  // Folds both payload shapes into [{ name, modes: [{ name, variables: [{ name, type, value, scopes, codeSyntax }] }] }].
  //   formatter output: { modes: ["light", "dark"], variables: [{ name, type, values: { light, dark } }] }
  //   per-mode:         { modes: [{ name, variables: [{ name, type, value }] }] }
  function normalizeCollection(c) {
    const modes = Array.isArray(c.modes) ? c.modes : [];
    if (modes.length > 0 && typeof modes[0] === "object") return c;
    const names = modes.length > 0 ? modes.map(String) : ["default"];
    const vars = Array.isArray(c.variables) ? c.variables : [];
    return {
      name: c.name,
      modes: names.map((name) => ({
        name,
        variables: vars
          .filter((v) => v && v.values && v.values[name] !== undefined)
          .map((v) => ({ name: v.name, type: v.type, value: v.values[name], scopes: v.scopes, codeSyntax: v.codeSyntax })),
      })),
    };
  }

  function figmaVarType(t) {
    switch ((t || "").toLowerCase()) {
      case "color": return "COLOR";
      case "number":
      case "float":
      case "size":
      case "spacing":
      case "radius": return "FLOAT";
      case "boolean": return "BOOLEAN";
      default: return "STRING";
    }
  }

  function normChan(c) {
    if (typeof c !== "number") return 0;
    return c > 1 ? c / 255 : c;
  }

  function hexToFigmaColor(hex) {
    const h = hex.replace("#", "");
    const full = h.length === 3 ? h.split("").map((x) => x + x).join("") : h;
    const r = parseInt(full.slice(0, 2), 16) / 255;
    const g = parseInt(full.slice(2, 4), 16) / 255;
    const b = parseInt(full.slice(4, 6), 16) / 255;
    const a = full.length === 8 ? parseInt(full.slice(6, 8), 16) / 255 : 1;
    return { r, g, b, a };
  }

  function coerceValue(type, v) {
    if (v === undefined || v === null) return undefined;
    const t = (type || "").toLowerCase();
    if (t === "color") {
      if (typeof v === "string") return hexToFigmaColor(v);
      if (typeof v === "object" && "r" in v) {
        return {
          r: normChan(v.r),
          g: normChan(v.g),
          b: normChan(v.b),
          a: typeof v.a === "number" ? (v.a > 1 ? v.a / 255 : v.a) : 1,
        };
      }
    }
    if (t === "number" || t === "float" || t === "size" || t === "spacing" || t === "radius") {
      const n = typeof v === "string" ? parseFloat(v) : v;
      return typeof n === "number" && !Number.isNaN(n) ? n : undefined;
    }
    if (t === "boolean") return Boolean(v);
    return String(v);
  }

  function isAlias(v) {
    return !!v && typeof v === "object" && v.type === "VARIABLE_ALIAS";
  }

  // --- Variables, pass 1: collections, modes and the variables themselves ---
  const existingCollections = await figma.variables.getLocalVariableCollectionsAsync();
  const existingVariables = await figma.variables.getLocalVariablesAsync();
  const collectionByName = new Map(existingCollections.map((c) => [c.name, c]));
  const variableByKey = new Map(existingVariables.map((v) => [v.variableCollectionId + "|" + v.name, v]));
  const plans = [];

  for (const rawCollection of raw) {
    const c = normalizeCollection(rawCollection);
    const modes = c.modes;
    const name = c.name || "designlang";
    let collection = collectionByName.get(name);
    let modeIds;
    if (!collection) {
      collection = figma.variables.createVariableCollection(name);
      collectionByName.set(name, collection);
      // First mode: rename the default one Figma auto-creates.
      collection.renameMode(collection.modes[0].modeId, modes[0].name || "Default");
      modeIds = [collection.modes[0].modeId];
      for (let i = 1; i < modes.length; i++) modeIds.push(collection.addMode(modes[i].name || "Mode " + (i + 1)));
    } else {
      modeIds = modes.map((m, i) => {
        const found = collection.modes.find((x) => x.name === (m.name || (i === 0 ? "Default" : "Mode " + (i + 1))));
        return found ? found.modeId : collection.addMode(m.name || "Mode " + (i + 1));
      });
    }
    result.collections++;

    const entries = [];
    const byName = new Map();
    for (let m = 0; m < modes.length; m++) {
      for (const v of Array.isArray(modes[m].variables) ? modes[m].variables : []) {
        if (!v || !v.name) continue;
        let variable = byName.get(v.name);
        if (!variable) {
          const key = collection.id + "|" + v.name;
          variable = variableByKey.get(key);
          if (!variable) {
            variable = figma.variables.createVariable(v.name, collection, figmaVarType(v.type));
            variableByKey.set(key, variable);
          }
          byName.set(v.name, variable);
          if (Array.isArray(v.scopes)) variable.scopes = v.scopes;
          if (v.codeSyntax && v.codeSyntax.WEB) variable.setVariableCodeSyntax("WEB", v.codeSyntax.WEB);
          result.variables++;
        }
        entries.push({ variable, type: v.type, value: v.value, modeId: modeIds[m] });
      }
    }
    plans.push({ collection, entries });
  }

  // --- Variables, pass 2: values and aliases (every target exists by now) ---
  for (const { entries } of plans) {
    for (const e of entries) {
      if (isAlias(e.value)) {
        const target = collectionByName.get(e.value.collection) && variableByKey.get(collectionByName.get(e.value.collection).id + "|" + e.value.name);
        if (target) e.variable.setValueForMode(e.modeId, figma.variables.createVariableAlias(target));
        continue;
      }
      const value = coerceValue(e.type, e.value);
      if (value !== undefined) e.variable.setValueForMode(e.modeId, value);
    }
  }

  function findVariable(collectionName, name) {
    const col = collectionByName.get(collectionName);
    return col ? variableByKey.get(col.id + "|" + name) : undefined;
  }

  // --- Text styles ---
  const textStyles = Array.isArray(payload.textStyles) ? payload.textStyles : [];
  const weightStyles = { 400: ["Regular"], 500: ["Medium"], 600: ["Semi Bold", "SemiBold"], 700: ["Bold"] };
  let availableFonts = null;
  const loaded = new Set();

  async function tryLoad(family, style) {
    const key = family + "|" + style;
    if (availableFonts && !availableFonts.has(key)) return false;
    if (loaded.has(key)) return true;
    try {
      await figma.loadFontAsync({ family, style });
      loaded.add(key);
      return true;
    } catch (e) {
      return false;
    }
  }

  // family+style, else Inter+style, else Inter Regular.
  async function resolveFont(family, weight) {
    if (!availableFonts) {
      availableFonts = new Set((await figma.listAvailableFontsAsync()).map((f) => f.fontName.family + "|" + f.fontName.style));
    }
    const styles = weightStyles[weight] || (weight >= 700 ? weightStyles[700] : weight >= 600 ? weightStyles[600] : weight >= 500 ? weightStyles[500] : weightStyles[400]);
    for (const s of styles) if (await tryLoad(family, s)) return { family, style: s, fallback: false };
    for (const s of styles) if (await tryLoad("Inter", s)) return { family: "Inter", style: s, fallback: family !== "Inter" };
    await tryLoad("Inter", "Regular");
    return { family: "Inter", style: "Regular", fallback: family !== "Inter" };
  }

  if (textStyles.length > 0) {
    const existing = await figma.getLocalTextStylesAsync();
    for (const t of textStyles) {
      if (!t || !t.name || !(t.fontSize >= 1)) continue;
      const font = await resolveFont(t.fontFamily || "Inter", Number(t.fontWeight) || 400);
      const style = existing.find((s) => s.name === t.name) || figma.createTextStyle();
      style.name = t.name;
      style.fontName = { family: font.family, style: font.style };
      style.fontSize = t.fontSize;
      style.lineHeight = typeof t.lineHeight === "number" ? { value: t.lineHeight, unit: "PIXELS" } : { unit: "AUTO" };
      style.letterSpacing = { value: t.letterSpacing || 0, unit: "PIXELS" };
      style.description = font.fallback ? "Brand font: " + t.fontFamily + " (fallback Inter)" : "";
      if (font.fallback) result.fontFallbacks.push({ style: t.name, wanted: t.fontFamily, used: font.family + " " + font.style });
      result.textStyles++;
    }
  }

  // --- Effect styles ---
  const effectStyles = Array.isArray(payload.effectStyles) ? payload.effectStyles : [];
  if (effectStyles.length > 0) {
    const existing = await figma.getLocalEffectStylesAsync();
    for (const e of effectStyles) {
      if (!e || !e.name) continue;
      const style = existing.find((s) => s.name === e.name) || figma.createEffectStyle();
      style.name = e.name;
      style.effects = (e.effects || []).map((fx) => ({
        type: fx.type,
        color: fx.color,
        offset: fx.offset,
        radius: fx.radius,
        spread: fx.spread || 0,
        visible: true,
        blendMode: "NORMAL",
      }));
      result.effectStyles++;
    }
  }

  // --- Button component set (opt-in) ---
  const hints = (Array.isArray(payload.components) ? payload.components : []).filter((c) => c && c.kind === "button");
  const alreadyBuilt = figma.currentPage.children.some((n) => n.type === "COMPONENT_SET" && n.name === "Button");
  if (opts.components && hints.length > 0 && !alreadyBuilt) {
    const label = await resolveFont("Inter", 500);

    // Variable holding exactly this number in Spacing / the given prefix, for binding.
    const numberVar = (prefix, n) => {
      const col = collectionByName.get("Spacing");
      if (!col) return undefined;
      for (const [key, v] of variableByKey) {
        if (key.indexOf(col.id + "|" + prefix) === 0 && v.valuesByMode && Object.values(v.valuesByMode)[0] === n) return v;
      }
      return undefined;
    };

    function paintFor(spec) {
      if (!spec) return undefined;
      if (isAlias(spec)) {
        const variable = findVariable(spec.collection, spec.name);
        if (!variable) return undefined;
        return figma.variables.setBoundVariableForPaint({ type: "SOLID", color: { r: 0, g: 0, b: 0 } }, "color", variable);
      }
      const c = hexToFigmaColor(spec);
      return { type: "SOLID", color: { r: c.r, g: c.g, b: c.b } };
    }

    const comps = [];
    for (const h of hints) {
      const comp = figma.createComponent();
      comp.name = "Variant=" + h.variant;
      comp.layoutMode = "HORIZONTAL";
      comp.primaryAxisAlignItems = "CENTER";
      comp.counterAxisAlignItems = "CENTER";
      comp.paddingTop = comp.paddingBottom = h.paddingY || 0;
      comp.paddingLeft = comp.paddingRight = h.paddingX || 0;
      comp.cornerRadius = h.radius || 0;
      const fill = paintFor(h.fill);
      comp.fills = fill ? [fill] : [];

      const py = numberVar("spacing/", h.paddingY);
      const px = numberVar("spacing/", h.paddingX);
      const rad = numberVar("radius/", h.radius);
      if (py) { comp.setBoundVariable("paddingTop", py); comp.setBoundVariable("paddingBottom", py); }
      if (px) { comp.setBoundVariable("paddingLeft", px); comp.setBoundVariable("paddingRight", px); }
      if (rad) for (const k of ["topLeftRadius", "topRightRadius", "bottomLeftRadius", "bottomRightRadius"]) comp.setBoundVariable(k, rad);

      const text = figma.createText();
      text.fontName = { family: label.family, style: label.style };
      text.characters = "Button";
      const textPaint = paintFor(h.text);
      if (textPaint) text.fills = [textPaint];
      comp.appendChild(text);
      comps.push(comp);
    }
    const set = figma.combineAsVariants(comps, figma.currentPage);
    set.name = "Button";
    result.components = comps.length;
  }

  return result;
}

figma.showUI(__html__, { width: 420, height: 480, themeColors: true });

figma.ui.onmessage = async (msg) => {
  if (msg.type === "cancel") {
    figma.closePlugin();
    return;
  }
  if (msg.type !== "import") return;

  try {
    const r = await importDesignSystem(figma, msg.data, { components: !!msg.components });
    figma.ui.postMessage({
      type: "done",
      variableCount: r.variables,
      collectionCount: r.collections,
      textStyleCount: r.textStyles,
      effectStyleCount: r.effectStyles,
      componentCount: r.components,
      fontFallbacks: r.fontFallbacks,
    });
    figma.notify(`designlang: imported ${r.variables} variables across ${r.collections} collections.`);
  } catch (err) {
    figma.ui.postMessage({ type: "error", message: err.message });
  }
};
